CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),sku text UNIQUE NOT NULL,name text NOT NULL,category text NOT NULL,description text NOT NULL DEFAULT '',unit text NOT NULL CHECK(unit IN ('m2','unidad','ml')),price numeric(14,2) NOT NULL CHECK(price>=0),available boolean NOT NULL DEFAULT true,needs_review boolean NOT NULL DEFAULT true,image_url text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS product_images(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),product_id uuid REFERENCES products(id),url text NOT NULL);
CREATE TABLE IF NOT EXISTS customers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),first_name text NOT NULL,last_name text NOT NULL,email text NOT NULL,phone text NOT NULL,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS customer_addresses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),customer_id uuid REFERENCES customers(id),department text,municipality text,district text,address text,reference text);
CREATE TABLE IF NOT EXISTS quotes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),number text UNIQUE NOT NULL,access_hash text NOT NULL,customer_id uuid NOT NULL REFERENCES customers(id),status text NOT NULL CHECK(status IN ('PENDIENTE_REVISION','EMITIDA','RECHAZADA','VENCIDA','CONVERTIDA')),subtotal numeric(14,2) NOT NULL,discount numeric(14,2) NOT NULL DEFAULT 0,charges numeric(14,2) NOT NULL DEFAULT 0,total numeric(14,2) NOT NULL,notes text NOT NULL DEFAULT '',delivery text NOT NULL DEFAULT 'RETIRO',created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS quote_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),quote_id uuid NOT NULL REFERENCES quotes(id),product_id uuid REFERENCES products(id),name text NOT NULL,unit text NOT NULL,quantity numeric(14,4) NOT NULL CHECK(quantity>0),width_cm numeric(12,2),length_cm numeric(12,2),finish text NOT NULL DEFAULT '',notes text NOT NULL DEFAULT '',unit_price numeric(14,2) NOT NULL,line_total numeric(14,2) NOT NULL);
CREATE TABLE IF NOT EXISTS quote_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),quote_id uuid NOT NULL REFERENCES quotes(id),filename text NOT NULL,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),number text NOT NULL UNIQUE,quote_id uuid NOT NULL UNIQUE REFERENCES quotes(id),customer_id uuid NOT NULL REFERENCES customers(id),status text NOT NULL DEFAULT 'PENDIENTE_DATOS',delivery jsonb,invoice_receiver jsonb,subtotal numeric(14,2) NOT NULL,total numeric(14,2) NOT NULL,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS order_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES orders(id),description text NOT NULL,quantity numeric(14,4) NOT NULL,unit text NOT NULL,price numeric(14,2) NOT NULL,total numeric(14,2) NOT NULL);
CREATE TABLE IF NOT EXISTS payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES orders(id),idempotency_key text NOT NULL,provider text NOT NULL DEFAULT 'SANDBOX',status text NOT NULL DEFAULT 'PENDING',amount numeric(14,2) NOT NULL,reference text,created_at timestamptz DEFAULT now(),UNIQUE(order_id,idempotency_key));
CREATE UNIQUE INDEX IF NOT EXISTS only_one_approved_payment ON payments(order_id) WHERE status='APPROVED';
CREATE TABLE IF NOT EXISTS payment_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),payment_id uuid REFERENCES payments(id),status text NOT NULL,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS invoices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL UNIQUE REFERENCES orders(id),status text NOT NULL CHECK(status IN ('BORRADOR','PENDIENTE','AUTORIZADA','RECHAZADA')),json_data jsonb,seal text,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS invoice_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),invoice_id uuid REFERENCES invoices(id),filename text NOT NULL);
CREATE TABLE IF NOT EXISTS order_status_history(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid REFERENCES orders(id),status text NOT NULL,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS company_settings(key text PRIMARY KEY,value text NOT NULL);
CREATE TABLE IF NOT EXISTS audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event text NOT NULL,ref_id uuid,detail jsonb,created_at timestamptz DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_products_category ON products(category);CREATE INDEX IF NOT EXISTS idx_quotes_customer ON quotes(customer_id);CREATE INDEX IF NOT EXISTS idx_orders_customer ON orders(customer_id);
